FIELDS = ("code", "label", "depot")


def _clean(value: str):
    stripped = value.strip()
    return stripped or None


def parse_row(line: str) -> dict:
    parts = line.split(",")
    return {name: _clean(parts[index]) for index, name in enumerate(FIELDS)}

